["def check(x, y):
    return 0 <= x < 8 and 0 <= y < 8

def dfs1(x, y, T=0):
    nonlocal first, used
    if not(check(x, y)) or used[x][y]:
        return
    used[x][y] = True
    first.add((x, y, T))
    for pair in (2, 2), (2, -2), (-2, 2), (-2, -2):
        dfs1(x + pair[0], y + pair[1], 1 - T)

def dfs2(x, y, T=0):
    nonlocal second, used
    if not(check(x, y)) or used[x][y]:
        return
    used[x][y] = True
    second.add((x, y, T))
    for pair in (2, 2), (2, -2), (-2, 2), (-2, -2):
        dfs2(x + pair[0], y + pair[1], 1 - T)


