def topological_sort(graph) -> list:
    n = len(graph)
    degree = [0] * n
    for g in graph:
        for next_pos in g:
            degree[next_pos] += 1

    ans = [i for i in range(n) if degree[i] == 0]

    stack = ans[:]
    while stack:
        pos = stack.pop()
        for next_pos in graph[pos]:
            degree[next_pos] -= 1
            if degree[next_pos] == 0:
                stack.append(next_pos)
                ans.append(next_pos)
    return ans



