def count(n, k, field):
    blank = 0
    cnt = [[0] * (n - k + 1) for _ in range(n)]
    for i, row in enumerate(field):
        l = row.find('B')
        r = row.rfind('B')
        if l == r == -1:
            blank += 1
            continue
        if r - l + 1 > k:
            continue
        kl = max(0, r - k + 1)
        kr = min(l + 1, n - k + 1)
        cnt[i][kl:kr] = [1] * (kr - kl)

    acc = [[0] * (n - k + 1) for _ in range(n - k + 1)]
