def addRect(x0,x1,y0,y1):
    nonlocal cum,n,k
    x0 = max(x0,0)+1
    x1 = min(x1,n-k)+1
    y0 = max(y0,0)+1
    y1 = min(y1,n-k)+1
    #print("HA",x0,x1,y0,y1)
    if x0 > x1 or y0 > y1:
        return
    #print("BEF",x0,x1,cum[1][1])
    cum[x0][y0] += 1
    #print("??",cum[1][1])
    cum[x1+1][y0] -= 1
    #print("??",x1+1,y0,cum[1][1],len(cum))
    cum[x0][y1+1] -= 1
    #print("??",cum[1][1])
    cum[x1+1][y1+1] += 1
