        for j in range(n):
            if L[i][j] == 'B':
                mx = j
                if mn == MOD:
                    mn = j
        if mn == MOD:
            cum[1][1] += 1
            continue
        #print(i,mn,mx,mx-k+1,mn)
        addRect(i-k+1,i,mx-k+1,mn)
    for j in range(n):
        mn,mx = MOD,-MOD
        for i in range(n):
            if L[i][j] == 'B':
                mx = i
                if mn == MOD:
                    mn = i
        if mn == MOD:
            cum[1][1] += 1
            continue
        #print(j,mn,mx)
        addRect(mx-k+1,mn,j-k+1,j)
    ans = 0
    for i in range(1,n+1):
        for j in range(1,n+1):
            cum[i][j] += cum[i][j-1]+cum[i-1][j]-cum[i-1][j-1]
            #print("HUH",i,j,cum[i][j])
            ans = max(ans,cum[i][j])
    return ans

