", "from itertools import permutations

def solve(TL, TR, BL, BR, s, n):
	A = []

	for i in range(n):
		X = TL[i].copy()
		X.extend(TR[i])
		A.append(X)

	for i in range(n):
		X = BL[i].copy()
		X.extend(BR[i])
		A.append(X)

	c = 0
	ans = 0

	for i in range(2 * n):
		if i % 2 == 1:
			c = s ^ 1
		else:
			c = s

		for j in range(2 * n):
			if A[i][j] != c:
				ans += 1
				A[i][j] = c

			c ^= 1

	return ans


