            population_snapshots[index] = population_snapshots[index - 1] + 1
        else:
            population_snapshots[index] = 1

    def copy(index):
        if index > 0:
            population_snapshots[index] = population_snapshots[index - 1]
        else:
            population_snapshots[index] = 0

    def decrease(index):
        population_snapshots[index] = population_snapshots[index - 1] - 1

    def increment_upto(end):
