        elif b == "1":
          last_branch = (current, "1")
      if b == "0":
        current = current.left
      elif b == "1":
        current = current.right

    current.value = current.value - 1
    if current.value == 0:
      if last_branch[1] == "0":
        last_branch[0].left = None
      elif last_branch[1] == "1":
        last_branch[0].right = None

