def to_mixed_frac(first, second):
    while True:
        for i in range(2, first + 1):
            if first % i == 0 and second % i == 0:
                first //= i
                second //= i
                break
        else:
            break
    return str(first) + "/" + str(second)


def array_to_int(array):
    for i in range(len(array)):
        array[i] = int(array[i])
    return array


def join0(array):
    result = ""
    for i in array:
        result += str(i)
    return result


