def solve(S, T):
    pos_s = {}
    pos_t = {}
    wrongs = []
    distance = 0

    for i, (s, t) in enumerate(zip(S,T)):
        if s != t:
            pos_t[(s,t)] = i
            pos_s[s] = i
            wrongs.append((s,t,i))
            distance += 1

    for wrong, need, i in wrongs:
        j = pos_t.get((need, wrong))
