    rps[v] += 1
  ret = inf
  visited = [False for i in range(vc+1)]
  for u in range(1, vc+1):
    r = dfs(graph, u, visited, rps)
    if ret > r: ret = r
  if ret == inf: ret = -1
  print(ret)

