    for (a, b) in pairs:
       recognitions[a].add(b)
       recognitions[b].add(a)

    minr = float('inf')

    for candidate, recognition in [(c, rs) for c, rs in list(recognitions.items()) if len(rs) > 1]:
        for c2, c3 in [(a, b) for a, b in combinations(recognition, 2)
                                if a in recognitions[b]]:
