def topological_sort(G, ans, k = '', visited = {}):
    if visited.get(k, True) == False:
        return True
    if k not in visited:
        visited[k] = False
        for next in G.get(k, []):
            if topological_sort(G, ans, next, visited):
                return True
        visited[k] = True
        ans.insert(0, k)
    return False

