		if len(shared) >= 3:
			return 3
		elif len(shared)==2:
			u, v = shared
			adj[u].append(v)
			adj[v].append(u)

	vis = [False for u in range(n)]
	dist = [-1 for u in range(n)]
	def shortest_cycle(n,adj,s):
		frontier = [(s,-1)]
		dist[s] = 0
		ptr = 0

		while ptr < len(frontier):
			u, p = frontier[ptr]
			if not vis[u]:
				vis[u] = True
				for v in adj[u]:
					if vis[v] and v != p:
