def shortest_path(u, v, g):
    q = [w for w in g[u] if w != v]
    vis = set(q) | {u}
    d = 0
    while q:
        d += 1
        nq = []
        for w in q:
            if w == v:
                return d
            for x in g[w]:
                if x not in vis:
                    vis.add(x)
                    nq.append(x)
        q = nq

    return float('inf')


