    if 1 not in ss:
        i = b.index(1)
        bf = 1
        for j in range(i,n):
            if b[j] != j - i + 1:
                bf = 0
                break
        if bf:
            t = b[-1]
            s = ss | set()
            for j in range(n-t):
                if t+j+1 not in s:
