                    break
                s.add(b[j])
            if bf:
                return n - t

    def f(i):
        s = ss | set(b[:i])
        for j in range(1,n+1):
            if j not in s:
                return True
            if i + j <= n:
                s.add(b[i+j-1])

        return False

    r = bs(f,0,n)

    return r + n


