from sys import stdin
from copy import deepcopy
from collections import deque



def find_start(pile):
	start = 1
	index = -1

	for i in range(len(pile)):
		if pile[i] == start:
			index = i
			break
	latest = start
	if index != -1:
		flag = True
		for i in range(index, len(pile)):
			if pile[i] == latest:
				latest += 1
			else:
				flag = False
				break

		if flag:
			start = latest
	return start


