    if len(arr)==2:
        if arr[0]=='IN':
            Type[i] = 'IN'
            Val[i]  = int(arr[1])
        else:
            Type[i]=arr[0]
            push(g, i, int(arr[1])-1)
    else:
        type_, v1, v2 = arr[0], int(arr[1]), int(arr[2])  
